// The solar system in a 200 AU cube: the Sun, the planets, the Moon, Pluto and the Galilean moons where they really
// are today (VSOP87 and the moon models of astronomy-engine); the other dwarf planets and the big asteroids on their
// Kepler ellipses, the other moons on circles of the real radius (both approximate, and the facts say so); and the
// asteroid and Kuiper belts as procedural populations at the real density, generated by the 0.2 AU leaves they fall in.
import { useMemo } from 'react'
import { BufferGeometry, Line, LineBasicMaterial, Vector3 } from 'three'
import { Body, Ecliptic, GeoMoon, HelioVector, JupiterMoons, MakeTime, Vector } from 'astronomy-engine'
import { hash, inCell, mulberry32, type ChildSpec, type Far, type Vec3 } from '../engine/tree'
import { PERF } from '../engine/perf'
import { rootProps, volume, type Region, type Volume } from './volume'
import { PLANETS, cubeOf } from './planet'
import { density, diameter, kepler, peak, type Belt, type Elements } from './orbits'

export const AU = 1.496e11
export const SIDE = 200 * AU // Eris and Sedna are 95 and 83 AU out today
export const EPOCH = new Date()
const YEAR = 1970 + EPOCH.getTime() / (365.25 * 864e5)
const T = MakeTime(EPOCH)
const SUN_R = 6.96e8
const LEAF = 10 // 0.2 AU leaves: a few hundred belt bodies each at most

// ecliptic position in cube units, with the orbital plane horizontal and north up
const place = (v: { x: number; y: number; z: number }): Vec3 => [(v.x * AU) / SIDE, (v.z * AU) / SIDE, (-v.y * AU) / SIDE]
const helio = (b: Body, date = EPOCH) => place(Ecliptic(HelioVector(b, date)).vec)
const ecl = (x: number, y: number, z: number) => Ecliptic(new Vector(x, y, z, T)).vec // J2000 equatorial to ecliptic
const add = (a: Vec3, b: Vec3): Vec3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]]
const row = (name: string) => PLANETS.findIndex(p => p.name === name)

// a moon on a circle of radius a (m) in its planet's equatorial plane (the pole: J2000 right ascension and
// declination, degrees), phased by its period from J2000: the circle is real, the spot on it is not known here
function circle(planet: Vec3, a: number, days: number, [ra, dec]: readonly [number, number]): Vec3 {
  const d = Math.PI / 180, k = ecl(Math.cos(dec * d) * Math.cos(ra * d), Math.cos(dec * d) * Math.sin(ra * d), Math.sin(dec * d))
  const n = Math.hypot(k.x, k.y), u = [-k.y / n, k.x / n, 0], v = [-k.z * u[1], k.z * u[0], k.x * u[1] - k.y * u[0]] // the ascending node, and 90° on
  const th = (2 * Math.PI * (EPOCH.getTime() - Date.UTC(2000, 0, 1, 12))) / (days * 864e5), c = (Math.cos(th) * a) / AU, s = (Math.sin(th) * a) / AU
  return add(planet, place({ x: u[0] * c + v[0] * s, y: u[1] * c + v[1] * s, z: u[2] * c + v[2] * s }))
}
const POLE = { mars: [317.681, 52.887], saturn: [40.589, 83.537], uranus: [257.311, -15.175], neptune: [299.36, 43.46], pluto: [132.993, -6.163] } as const

const KEPLER = 'Position from its orbit alone, without the planets’ pulls: approximate.'
const GUESS = 'On its real orbit but at an arbitrary point of it: where it is today is not known here.'
const CIRCLE = 'Drawn on a circle of the real radius in its planet’s equatorial plane; where it is on that circle is not known here.'
// JPL elements; Pallas and Hygiea with an arbitrary perihelion passage (2000), the others with the real one
const ELLIPSES: [string, Elements, string][] = [
  ['Ceres', [2.7667, 0.0785, 10.59, 80.31, 73.6, 4.604, 2018.32], KEPLER],
  ['Vesta', [2.3615, 0.0894, 7.14, 103.85, 151.19, 3.629, 2018.4], KEPLER],
  ['Pallas', [2.7695, 0.2302, 34.93, 172.9, 310.9, 4.61, 2000], GUESS],
  ['Hygiea', [3.1415, 0.1125, 3.83, 283.2, 312.3, 5.57, 2000], GUESS],
  ['Eris', [67.86, 0.4361, 44.04, 35.95, 151.64, 559.1, 2257.4], KEPLER],
  ['Makemake', [45.43, 0.161, 28.98, 79.62, 294.83, 306.2, 1879.5], KEPLER],
  ['Haumea', [43.12, 0.195, 28.21, 122.17, 239.04, 283.1, 2133.5], KEPLER],
  ['Sedna', [506, 0.8496, 11.93, 144.25, 311.35, 11400, 2076.5], KEPLER],
]

function bodies(): ChildSpec[] {
  const earth = helio(Body.Earth), mars = helio(Body.Mars), jupiter = helio(Body.Jupiter), saturn = helio(Body.Saturn), uranus = helio(Body.Uranus), neptune = helio(Body.Neptune), pluto = helio(Body.Pluto)
  const moon = place(Ecliptic(GeoMoon(EPOCH)).vec)
  const jm = JupiterMoons(EPOCH)
  const planet = (name: string, pos: Vec3, note?: string): ChildSpec => {
    const p = row(name)
    return { kind: 'planet', pos, size: cubeOf(p) / SIDE, props: note ? { ...rootProps, p, fact: `${PLANETS[p].fact} ${note}` } : { ...rootProps, p } }
  }
  const galilean = (name: string, m: { x: number; y: number; z: number }) => planet(name, add(jupiter, place(ecl(m.x, m.y, m.z))))
  return [
    { kind: 'star', pos: [0, 0, 0], size: (2.2 * SUN_R) / SIDE, props: { ...rootProps, r: SUN_R, t: 5772, name: 'The Sun', fact: 'A ball of plasma 1.39 million km across, 333,000 Earths in mass, fusing 600 million tonnes of hydrogen a second. Everything else here is leftovers.' } },
    planet('Mercury', helio(Body.Mercury)),
    planet('Venus', helio(Body.Venus)),
    { kind: 'earth', pos: earth, size: 1.3e7 / SIDE, props: { ...rootProps } },
    planet('The Moon', add(earth, moon)),
    planet('Mars', mars),
    planet('Jupiter', jupiter),
    planet('Saturn', saturn),
    planet('Uranus', uranus),
    planet('Neptune', neptune),
    // everything below is appended, so the indices above (EARTH_KEY) hold
    planet('Pluto', pluto),
    planet('Charon', circle(pluto, 1.9591e7, 6.3872, POLE.pluto), CIRCLE),
    ...ELLIPSES.map(([name, el, note]) => planet(name, place(kepler(el, YEAR)), note)),
    galilean('Io', jm.io),
    galilean('Europa', jm.europa),
    galilean('Ganymede', jm.ganymede),
    galilean('Callisto', jm.callisto),
    planet('Titan', circle(saturn, 1.22187e9, 15.945, POLE.saturn), CIRCLE),
    planet('Enceladus', circle(saturn, 2.37948e8, 1.37, POLE.saturn), CIRCLE),
    planet('Rhea', circle(saturn, 5.27108e8, 4.518, POLE.saturn), CIRCLE),
    planet('Iapetus', circle(saturn, 3.56082e9, 79.32, POLE.saturn), CIRCLE),
    planet('Titania', circle(uranus, 4.3591e8, 8.706, POLE.uranus), CIRCLE),
    planet('Oberon', circle(uranus, 5.8352e8, 13.463, POLE.uranus), CIRCLE),
    planet('Triton', circle(neptune, 3.54759e8, 5.877, POLE.neptune), CIRCLE),
    planet('Phobos', circle(mars, 9.376e6, 0.3189, POLE.mars), CIRCLE),
    planet('Deimos', circle(mars, 2.3463e7, 1.263, POLE.mars), CIRCLE),
  ]
}
export const EARTH_KEY = 's.11' // the Earth is the fourth placement after the eight octants

// ---- the belts ---------------------------------------------------------------------------------------------
// Counts over 1 km (the asteroid belt's is measured, the Kuiper belt's extrapolated from the few thousand seen),
// each a smooth ring, sizes N(>D) ∝ D⁻² up to 100 km and steeper beyond; the biggest bodies are placed by name above.
type Ring = Belt & { title: string; color: string; fact: string; p: (u: number) => number }
const [C, S, M, KBO] = ['Carbonaceous asteroid', 'Stony asteroid', 'Metallic asteroid', 'Kuiper belt object'].map(row)
const BELTS: Ring[] = [
  { title: 'Asteroid belt', r1: 2.1, r2: 3.3, w: 0.1, h: 0.1, n: 1.1e6, dmin: 1, q: 2, brk: 100, q2: 2.4, dmax: 500, color: '#b0a898', p: u => (u < 0.75 ? C : u < 0.92 ? S : M),
    fact: 'Between Mars and Jupiter, 2.1 to 3.3 AU out: about 1.1 million bodies over a kilometre across, three in four of them dark carbonaceous rock, together 3% of the Moon’s mass and a third of that in Ceres. Still nearly empty: neighbours are millions of km apart. Drawn as a smooth ring with the real counts and sizes; the real belt has gaps swept clear by Jupiter.' },
  { title: 'Kuiper belt', r1: 30, r2: 50, w: 1.5, h: 0.12, n: 1e9, dmin: 1, q: 2, brk: 100, q2: 4.3, dmax: 800, color: '#b8c8d8', p: () => KBO,
    fact: 'A ring of icy leftovers past Neptune, 30 to 50 AU out: some 100,000 bodies over 100 km and perhaps a billion over a kilometre (an extrapolation; a few thousand have been seen), in all a few hundredths of the Earth’s mass. Drawn as a smooth ring; the real belt is clumped into resonances with Neptune, like Pluto’s.' },
]
const K = SIDE / AU
const at = (b: Belt, c: Vec3) => density(b, Math.hypot(c[0], c[2]) * K, Math.abs(c[1]) * K) * K ** 3 // bodies per cube-unit³
const alphaOf = (mean: number) => Math.min(1, Math.max(0.12, Math.log10(mean / PERF.samples) / 6 + 0.12)) // samples stand for up to millions: brighter for more

// the belt bodies of a region, in region units: the first `limit` of them, the same ones whatever the limit
function eachBody(r: Region, rng: () => number, limit: number, body: (b: Ring, pos: Vec3, km: number, p: number) => void) {
  let k = 0
  for (const b of BELTS) {
    const mean = at(b, r.c) * r.s ** 3
    let n = Math.floor(mean) + (rng() < mean - Math.floor(mean) ? 1 : 0)
    while (n-- > 0 && k++ < limit) body(b, [rng() - 0.5, rng() - 0.5, rng() - 0.5], diameter(b, rng), b.p(rng()))
  }
}

const ORBITS: [Body, number][] = [[Body.Mercury, 0.241], [Body.Venus, 0.615], [Body.Earth, 1], [Body.Mars, 1.881], [Body.Jupiter, 11.86], [Body.Saturn, 29.46], [Body.Uranus, 84.0], [Body.Neptune, 164.8], [Body.Pluto, 247.9]]

function Orbits() {
  const lines = useMemo(() => ORBITS.map(([b, years], i) => {
    // one orbit from today, closed back onto today's position: a year of perturbations would otherwise leave the
    // two ends thousands of km apart, which is a visible gap once you are down at the planet
    const pts = Array.from({ length: 180 }, (_, k) => new Vector3(...helio(b, new Date(EPOCH.getTime() + (k / 180) * years * 365.25 * 864e5))))
    pts.push(pts[0].clone())
    return new Line(new BufferGeometry().setFromPoints(pts), new LineBasicMaterial({ color: i === 2 ? '#4a7fc0' : '#ffffff', transparent: true, opacity: i === 2 ? 0.7 : 0.3 }))
  }), [])
  return <group>{lines.map((l, i) => <primitive key={i} object={l} />)}</group>
}

const solar: Volume = {
  deep: true,
  leafDepth: () => LEAF,
  placeDepth: () => 0,
  placements: () => bodies(),
  Near: Orbits,

  fill: (r, rng) => {
    const out: ChildSpec[] = []
    eachBody(r, rng, Infinity, (_, pos, km, p) => out.push({ kind: 'planet', pos, size: cubeOf(p, km * 500) / (r.s * SIDE), props: { ...rootProps, p, r: km * 500 } }))
    return out
  },

  far: (r, node) => {
    if (r.depth === 0) return { shape: 'sphere', color: '#fff3dc', glow: true, scale: (2.2 * SUN_R) / SIDE, minPx: 3 }
    const out: Far[] = []
    if (r.depth === LEAF) { // a closed leaf: the first few dozen of the bodies it will generate, so they stay put when it opens
      const alpha = alphaOf(BELTS.reduce((s, b) => s + at(b, r.c), 0) * r.s ** 3)
      eachBody(r, mulberry32(node.seed), PERF.samples, (b, pos) => out.push({ shape: 'point', color: b.color, pos, alpha }))
    } else { // a bigger region: points drawn from the density at 27 points of it, a cell by its weight and anywhere within
      const rng = mulberry32(hash(node.seed, 0x57a))
      for (const b of BELTS) {
        const w = [-0.5, 0, 0.5].flatMap(x => [-0.5, 0, 0.5].flatMap(y => [-0.5, 0, 0.5].map(z => at(b, [r.c[0] + x * r.s, r.c[1] + y * r.s, r.c[2] + z * r.s]))))
        const total = w.reduce((a, c) => a + c, 0), mean = (total / 27) * r.s ** 3
        const n = Math.min(PERF.samples, Math.floor(mean) + (rng() < mean - Math.floor(mean) ? 1 : 0)), alpha = alphaOf(mean)
        for (let i = 0; i < n; i++) out.push({ shape: 'point', color: b.color, pos: inCell(w, total, rng), alpha })
      }
    }
    return out.length ? out : null
  },

  info: r => {
    const b = r.depth && BELTS.find(b => at(b, r.c) > 0.1 * peak(b) * K ** 3)
    return b ? { title: b.title, fact: b.fact } : { title: 'Solar system', fact: `The Sun and its planets as they are today (${EPOCH.toISOString().slice(0, 10)}): Neptune’s orbit is 60 AU across, 9 billion km, and almost all of it is empty.` }
  },
}

export const kinds = { solar: volume(solar) }
export { PLANETS }
